const item = $input.first();

// The Webhook node runs with Raw Body on, so the body arrives as a string
// (or as base64 binary when n8n decides it is not text). n8n has already
// rejected anything without the right Authorization header before this runs,
// so this node only has to parse - it is not a trust boundary.
let raw = $('Webhook').first().json.body;
if (typeof raw !== 'string') {
  raw = Buffer.from($('Webhook').first().binary?.data?.data ?? '', 'base64').toString('utf8');
}

let payload = null;
try {
  payload = JSON.parse(raw);
} catch (e) {
  throw new Error('Webhook body was not valid JSON: ' + String(raw).slice(0, 200));
}

return [{ json: { payload } }];

// project.label_added fires for ANY label on ANY project. This account has
// eight project labels (Website Showcase, Gutter Cleaning, JobNimbus Job,
// Pipedrive Deal, and four "... Lead" labels). Without this filter, someone
// tagging a project "Pipedrive Deal" starts building a WordPress draft.
//
// Payload shape, captured from a real delivery 2026-09-22 (webhook 282006):
//
//   { event_type, created_at, webhook_id,
//     payload: { project: {...}, label: {...} } }
//
// Two corrections to what docs/01-api-audit.md 1.3 assumed from the legacy
// docs, both found by that delivery:
//
// 1. The project is at payload.payload.PROJECT, not payload.payload. Reading
//    it one level too shallow gave an empty id, which produced a request to
//    /v2/projects//labels and a 404 that looked like a base-URL problem.
// 2. The event DOES carry the label that was added, as payload.payload.label.
//    So the fetch fallback is almost never needed -- and the label from the
//    event is strictly MORE precise than the fetch. The fetch asks "does this
//    project have the Website Showcase label at all", which is true when
//    someone adds Gutter Cleaning to an already-showcased project. The event
//    answers "which label was just added", which is the actual question.
const env = $input.first().json.payload || {};
const inner = env.payload || {};
const project = inner.project || {};
const label = inner.label || {};

const eventType = String(env.event_type || '');
const labelValue = String(label.value || label.display_value || '').toLowerCase();

// Only fall back to the API when the event carried no label at all, which
// would mean the payload shape changed again.
const needsLabelFetch = labelValue === '';

return [{
  json: {
    eventType,
    projectId: String(project.id || ''),
    labelValue,
    needsLabelFetch,
    isOurs:
      eventType === 'project.label_added' &&
      !needsLabelFetch &&
      labelValue === 'website showcase',
  },
}];

// Reached only when the delivered event carried no label at all -- i.e. the
// payload shape changed from what a real delivery showed on 2026-09-22. This
// is a safety net, not the normal path.
//
// Note this check is deliberately weaker than the one in Check Label: it can
// only ask whether the project carries the label, not which label was just
// added. A project that was already showcased will pass this when an
// unrelated label is added. That is the cost of losing the event's own label,
// and it is why this branch is the fallback rather than the default.
const ctx = $('Check Label').first().json;
const labels = $input.first().json;
const list = Array.isArray(labels) ? labels : (labels.data || []);

const isOurs = list.some(
  (l) => String(l.value || '').toLowerCase() === 'website showcase'
);

return [{ json: { ...ctx, isOurs } }];

// Both CompanyCam photo calls return a JSON *array*, and n8n splits an array
// response into one item per element. So $('Get Cover Photo').first().json is
// the first PHOTO, not the list -- read as a list it gives
// "showcase.filter is not a function". Use .all() and rebuild the array.
//
// Those two nodes also run with "Always Output Data" on, so a zero-photo
// response still emits a single empty item rather than nothing. Without it
// n8n counts the node as having produced no data, skips everything
// downstream, and the execution reports SUCCESS having created nothing --
// the silent-success bug from docs/07-phase-4-preflight.md section 15.4.
// Filtering on .id drops that empty sentinel so the throws below still fire.
const photosFrom = (node) =>
  $(node)
    .all()
    .map((item) => item.json)
    .filter((p) => p && p.id);

const projectRaw = $('Get Project').first().json;
const project = projectRaw.data || projectRaw;

const showcase = photosFrom('Get Showcase Photos');
const covers = photosFrom('Get Cover Photo');

// Hard filters: docs/01-api-audit.md sections 1.5 and 6.
const usable = showcase.filter(
  (p) => p.internal !== true && p.processing_status === 'processed'
);

// CompanyCam returns timestamps as Unix epoch SECONDS (an integer), not as
// an ISO string -- every *_at field in the webhook payload is one, and
// captured_at is no different. docs/01 recorded that captured_at exists and
// what it is for, but never its type.
//
// new Date(1789035125) reads that as MILLISECONDS and lands in January 1970.
// The sort survived it by luck (the mapping is monotonic, so the order is the
// same) but String(captured_at).slice(0, 10) produced "1789035125", which is
// not a date, and the plugin's sanitiser correctly dropped it -- leaving
// completion_date empty (docs/07-phase-4-preflight.md section 16.7).
//
// Handles an ISO string too, in case the endpoint ever returns one.
const capturedMs = (p) => {
  const raw = p && p.captured_at;
  if (typeof raw === 'number') {
    return raw * 1000;
  }
  const text = String(raw || '').trim();
  if (/^\d+$/.test(text)) {
    return Number(text) * 1000;
  }
  const parsed = Date.parse(text);
  return Number.isFinite(parsed) ? parsed : 0;
};

// Oldest first: before -> during -> after, the order the page reads in.
usable.sort((a, b) => capturedMs(a) - capturedMs(b));
const capped = usable.slice(0, 20);

const cover = covers[0] || null;

// Fail loudly rather than guess. docs/06-trigger-design.md section 3 requires
// a human to confirm the cover is a genuine hero shot - they cannot confirm a
// cover the automation picked at random. The fix for all three of these is in
// CompanyCam (pull the label, fix the curation), not in a draft that papers
// over it.
if (!cover) {
  throw new Error(`Project ${project.id}: no photo tagged "Showcase Cover".`);
}
if (covers.length > 1) {
  throw new Error(
    `Project ${project.id}: ${covers.length} photos tagged "Showcase Cover" - expected exactly 1.`
  );
}

// The cover is also tagged Showcase, so it is in both lists. Decided
// 2026-09-17: cover becomes featured_media, gallery is the set MINUS the
// cover, so no photo appears twice on the page.
const gallery = capped.filter((p) => p.id !== cover.id);

if (gallery.length === 0) {
  throw new Error(`Project ${project.id}: no gallery photos left after filtering.`);
}

// --- Pin offset ---------------------------------------------------------
// Generated HERE, once, and only the offset travels onward. The true
// coordinates are never written to WordPress at all - docs/05-data-model.md
// section 1. The plugin has no field for them and its tests assert none is
// ever added.
const lat = project.coordinates && project.coordinates.lat;
const lon = project.coordinates && project.coordinates.lon;

if (typeof lat !== 'number' || typeof lon !== 'number') {
  throw new Error(`Project ${project.id}: no coordinates to offset.`);
}

const R = 3958.8; // Earth radius, miles
const bearing = Math.random() * 2 * Math.PI;

// An annulus, not a disc: at least 0.2 mi, at most 0.3 mi
// (docs/04-pin-precision-research.md section 4). A uniform draw over a disc
// would sometimes land the pin almost on the house, defeating the offset.
const miles = 0.2 + Math.random() * 0.1;

const d = miles / R;
const la = (lat * Math.PI) / 180;
const lo = (lon * Math.PI) / 180;

const la2 = Math.asin(
  Math.sin(la) * Math.cos(d) + Math.cos(la) * Math.sin(d) * Math.cos(bearing)
);
const lo2 =
  lo +
  Math.atan2(
    Math.sin(bearing) * Math.sin(d) * Math.cos(la),
    Math.cos(d) - Math.sin(la) * Math.sin(la2)
  );

const city = (project.address && project.address.city) || '';
const areaSlug = city.toLowerCase().trim().replace(/[^a-z0-9]+/g, '-');

const pick = (p) => {
  const uris = p.uris || [];
  const original = uris.find((u) => u.type === 'original');
  const web = uris.find((u) => u.type === 'web');
  return (original || web || {}).uri;
};

// The caption a human typed on the photo in CompanyCam.
//
// This is the whole point of the page. Jacob, 2026-10-29, on the first draft:
// "all of that context, all of that emotion, all of that feeling, all of
// those details never got placed on this page." They were sitting in
// CompanyCam the whole time; nothing carried them across.
//
// `description` is NOT a string. On a photo that has one it is an object --
// { id, html_content, plain_text_content } -- and on one that does not it is
// null. The old audit recorded "description: null" on every Phase 1 photo,
// which is true and told us nothing about the populated shape. Read
// plain_text_content, and still handle a bare string in case the REST and MCP
// representations differ.
const caption = (p) => {
  const d = p && p.description;
  if (!d) return '';
  if (typeof d === 'string') return d.trim();
  return String(d.plain_text_content || '').trim();
};

return [{
  json: {
    companycamProjectId: String(project.id),
    city,
    areaSlug,
    zip: (project.address && project.address.postal_code) || '',
    approxLat: Number(((la2 * 180) / Math.PI).toFixed(6)),
    approxLng: Number(((lo2 * 180) / Math.PI).toFixed(6)),
    completionDate: capturedMs(cover)
      ? new Date(capturedMs(cover)).toISOString().slice(0, 10)
      : '',
    coverUrl: pick(cover),
    coverCaption: caption(cover),
    galleryUrls: gallery.map(pick),
    galleryCaptions: gallery.map(caption),
    // CompanyCam's Project Description -- what the app calls the notepad, and
    // where the project manager writes what actually happened on the job.
    // Carried through for the REVIEWER to write copy from, never for the page
    // (docs/12-project-notes-path.md). WordPress stores it in a field marked
    // private, which the plugin strips from the public REST response, because
    // notes like this routinely name the homeowner.
    fieldNotes: String(project.description || '').trim(),
  },
}];

const c = $('Curate').first().json;
// Same array-splitting rule as Curate: /wp/v2/service-areas returns a JSON
// array, so n8n hands us one item per term and .first().json is a single
// term. Get Area Term runs with "Always Output Data" on, so a no-match
// lookup arrives as one empty item; the .id filter drops it and the throw
// below fires instead of the branch ending quietly.
const terms = $('Get Area Term')
  .all()
  .map((item) => item.json)
  .filter((t) => t && t.id);

// A project whose city is not one of the eight service areas would otherwise
// be filed nowhere and drop out of every map widget. Throw instead.
if (!terms.length) {
  throw new Error(
    `No service_area term for slug "${c.areaSlug}" (city "${c.city}"). Expected one of the eight seeded areas.`
  );
}

const areaName = terms[0].name;

// Title and copy are deliberately minimal.
//
// docs/06-trigger-design.md section 3 locks the SEO title as one job, one
// town, roof replacement - e.g. "GAF Timberline HDZ Roof Replacement in Wake
// Forest, NC". That needs manufacturer and product line, and NOTHING
// populates those: there is no CompanyCam->ProLine bridge
// (docs/07-phase-4-preflight.md section 2.4.2). So write the town-only form
// and let the reviewer upgrade it after filling the product fields.
//
// The body is one factual sentence for the same reason. The locked copy rules
// forbid invented prices, "free roof", city-stuffing and storm claims, and an
// automation with no product data and no job notes has nothing true to say
// beyond the town and the service. Writing the 2-4 sentence description is the
// reviewer's job at the gate. A thin draft a human finishes beats a fluent one
// that invents specifics.
const title = `Roof Replacement in ${areaName}, NC`;
const content = `<p>Skybird Roofing completed a full roof replacement in ${areaName}, North Carolina.</p>`;

// Cover first, so the approval screen's "use as cover" radio defaults to the
// right photo and the gallery keeps Curate's oldest-first curation.
const pairs = [[c.coverUrl, c.coverCaption || '']]
  .concat(c.galleryUrls.map((u, i) => [u, (c.galleryCaptions || [])[i] || '']))
  .filter((p) => p[0]);

return [{
  json: {
    status: 'draft',
    title,
    content,
    excerpt: `Roof replacement in ${areaName}, NC.`,
    'service-areas': [terms[0].id],
    // No featured_media and no gallery. NOTHING is uploaded here any more.
    //
    // A WordPress attachment is a file on disk with a public URL the moment
    // the upload returns, and that URL does not care what status the post is
    // in. Uploading first and reviewing second meant the only irreversible
    // step happened before anyone looked — which published a homeowner's
    // name and address, and then a photo carrying GPS 17.6 ft from their door
    // (docs/07-phase-4-preflight.md sections 16.1 and 16.9).
    //
    // The draft now carries candidate URLs instead. The reviewer sees them in
    // wp-admin served from CompanyCam, ticks the ones that are fine, and only
    // those are ever fetched — through WordPress's own sideload path, so the
    // plugin's EXIF stripper runs on every one.
    //
    // Cover first: the approval screen defaults its "use as cover" radio to
    // the first photo, so the order carries Curate's choice without needing a
    // second field for it.
    meta: {
      companycam_project_id: c.companycamProjectId,
      approx_lat: c.approxLat,
      approx_lng: c.approxLng,
      // Photos and captions are zipped BEFORE filtering, then split again.
      //
      // The old line filtered the URL list on its own. A photo whose `pick()`
      // found no usable URI would be dropped from the middle of the array and
      // every caption after it would slide onto the wrong picture -- a
      // silent, plausible-looking misattribution rather than a visible error.
      // Pairing first makes the two lists impossible to misalign.
      pending_photos: pairs.map((p) => p[0]),
      pending_captions: pairs.map((p) => p[1]),
      city: c.city,
      zip: c.zip,
      completion_date: c.completionDate,
      field_notes: c.fieldNotes,
    },
  },
}];
